        selected["adopt_frac"] * 100, selected["savings_pct"], selected["failure_upper95"] * 100,
    ))
    print("NOTE: all tokens/costs are estimates; quality is an automatic proxy; held-out split pending.")


if __name__ == "__main__":
    main()

